import {useCallback,useEffect,useState,type FormEvent,type ReactNode} from 'react';
import {LayoutDashboard,Ticket as TicketIcon,Users,Building2,Shapes,ChartNoAxesCombined,Timer,FileDown,ScrollText,Settings,Search,Plus,ArrowUpRight,ArrowLeft,ChevronLeft,ChevronRight,CheckCircle2,Clock3,AlertCircle,Inbox,LogOut,Menu,RefreshCw,Send,ShieldCheck,SlidersHorizontal,Paperclip,MessageSquare,Activity,Bell,ChevronDown} from 'lucide-react';
import {AreaChart,Area,XAxis,YAxis,Tooltip,ResponsiveContainer,CartesianGrid,BarChart,Bar} from 'recharts';
import {api,date,setCsrf} from './api';
import {type User,type Ticket,type Receiver,type Catalog,type Stats,type Group,statuses,priorities,roleNames} from './types';
import {Dialog} from './components/ui/dialog';

const nav=[['overview','Обзор',LayoutDashboard],['tickets','Заявки',TicketIcon],['users','Сотрудники',Users],['receivers','АХО / Получатели',Send],['departments','Департаменты',Building2],['categories','Категории',Shapes],['analytics','Аналитика',ChartNoAxesCombined],['sla','SLA',Timer],['reports','Отчеты',FileDown],['audit','Журнал действий',ScrollText],['settings','Настройки',Settings]] as const;
const isManager=(u:User)=>u.roles.some(r=>['ADMIN','AHO_MANAGER'].includes(r));
const isStaff=(u:User)=>u.roles.some(r=>['ADMIN','AHO_MANAGER','AHO_SPECIALIST'].includes(r));
const badge=(value:string,label?:string)=><span className={'badge badge-'+value.toLowerCase()}><i/>{label||statuses[value]||value}</span>;
const empty=(text='Здесь пока нет записей')=><div className="empty"><Inbox size={30}/><strong>{text}</strong><span>Новые записи появятся здесь автоматически.</span></div>;
function Field({label,children}:{label:string;children:ReactNode}){return <label className="field"><span>{label}</span>{children}</label>;}
function Select({value,onChange,options,placeholder}:{value:string;onChange:(s:string)=>void;options:{id:string;name:string}[];placeholder?:string}){return <select value={value} onChange={e=>onChange(e.target.value)}>{placeholder&&<option value="">{placeholder}</option>}{options.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select>;}
function Login({onLogin}:{onLogin:(u:User)=>void}){
 const [email,setEmail]=useState('admin@example.local'),[password,setPassword]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState(false);
 async function submit(e:FormEvent){e.preventDefault();setBusy(true);setError('');try{const r=await api<{user:User;csrf:string}>('/auth/login','POST',{email,password});setCsrf(r.csrf);onLogin(r.user);}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
 return <div className="login"><div className="login-story"><div className="brand"><span className="brand-symbol"><Building2/></span><b>АХО<span>Сервис для сотрудников</span></b></div><div><span className="eyebrow">ВНУТРЕННИЙ СЕРВИС КОМПАНИИ</span><h1>Рабочие вопросы.<br/>Под контролем.</h1><p>Единое пространство для заявок, команды и заботы об офисе.</p><div className="login-features"><span><CheckCircle2 size={18}/> Прозрачная история обращений</span><span><Timer size={18}/> Контроль сроков и SLA</span><span><Send size={18}/> Уведомления в Telegram</span></div></div><small>АХО · Управление административными запросами</small></div><div className="login-main"><form onSubmit={submit}><span className="eyebrow">РАБОЧЕЕ ПРОСТРАНСТВО</span><h2>Добро пожаловать</h2><p>Войдите в учетную запись компании</p><Field label="Рабочая почта"><input type="email" autoComplete="username" value={email} onChange={e=>setEmail(e.target.value)} required/></Field><Field label="Пароль"><input type="password" autoComplete="current-password" value={password} onChange={e=>setPassword(e.target.value)} required/></Field>{error&&<div role="alert" className="error">{error}</div>}<button className="primary full" disabled={busy}>{busy?'Входим…':'Войти в систему'}<ArrowUpRight size={18}/></button><div className="login-note"><ShieldCheck size={18}/><span>Доступ предоставляется администратором.<br/>Сотрудникам также доступен Telegram-бот.</span></div></form></div></div>;
}

export default function App(){
 const [user,setUser]=useState<User|null>(null),[loading,setLoading]=useState(true),[page,setPage]=useState('overview'),[mobile,setMobile]=useState(false),[selected,setSelected]=useState<string|null>(null),[create,setCreate]=useState(false),[version,setVersion]=useState(0),[toast,setToast]=useState(''),[error,setError]=useState(''),[tz,setTz]=useState('Asia/Tashkent');
 const [cats,setCats]=useState<Catalog[]>([]),[deps,setDeps]=useState<Catalog[]>([]),[receivers,setReceivers]=useState<Receiver[]>([]);
 const refresh=useCallback(()=>setVersion(v=>v+1),[]);
 const notify=useCallback((s:string)=>{setToast(s);setTimeout(()=>setToast(''),4500);},[]);
 useEffect(()=>{api<{user:User;csrf:string;timezone:string}>('/auth/me').then(r=>{setUser(r.user);setCsrf(r.csrf);setTz(r.timezone);if(!isManager(r.user))setPage('tickets');}).catch(()=>{}).finally(()=>setLoading(false));},[]);
 useEffect(()=>{if(!user)return;Promise.all([api<Catalog[]>('/catalog/categories'),api<Catalog[]>('/catalog/departments'),isStaff(user)?api<Receiver[]>('/receivers'):Promise.resolve([])]).then(([c,d,r])=>{setCats(c);setDeps(d);setReceivers(r);}).catch(e=>setError(e.message));},[user,version]);
 const run=async(fn:()=>Promise<unknown>,message='Изменения сохранены')=>{setError('');try{await fn();refresh();notify(message);return true;}catch(e){setError((e as Error).message);return false;}};
 if(loading)return <div className="app-loading"><Building2 size={32}/><span>Загрузка рабочего пространства…</span></div>;
 if(!user)return <Login onLogin={u=>{setUser(u);setPage(isManager(u)?'overview':'tickets');}}/>;
 const admin=user.roles.includes('ADMIN'),management=isManager(user);
 const allowed=nav.filter(([id])=>admin||management&&!['audit','settings'].includes(id)||isStaff(user)&&['tickets'].includes(id)||id==='tickets');
 const go=(p:string)=>{setPage(p);setSelected(null);setMobile(false);setError('');};
 const common={user,run,refresh,notify,tz,cats,deps,receivers,version};
 return <div className="shell"><aside className={'sidebar '+(mobile?'show':'')}><a className="brand" onClick={()=>go(management?'overview':'tickets')}><span className="brand-symbol"><Building2 size={24}/></span><b>АХО<span>Управление заявками</span></b></a><div className="workspace"><span className="workspace-icon">КО</span><div>Компания<span>Главный офис</span></div><ChevronDown size={15}/></div><span className="nav-caption">РАБОЧЕЕ ПРОСТРАНСТВО</span><nav>{allowed.map(([id,label,Icon])=><button key={id} className={page===id?'active':''} onClick={()=>go(id)}><Icon size={19}/><span>{label}</span>{id==='tickets'&&<span className="nav-dot"/>}</button>)}</nav><div className="sidebar-bottom"><div className="service-state"><span/><div>Система обращений<small>Все заявки в одном месте</small></div></div><button className="user-chip" onClick={()=>go('profile')}><div className="avatar">{user.first_name[0]}{user.last_name[0]}</div><div><b>{user.first_name} {user.last_name}</b><small>{roleNames[user.roles.find(r=>r!=='EMPLOYEE')||'EMPLOYEE']}</small></div></button></div></aside><div className="main"><header className="topbar"><button className="icon-button mobile-menu" aria-label="Меню" onClick={()=>setMobile(!mobile)}><Menu size={22}/></button><div className="breadcrumb">Рабочее пространство <span>/</span> <b>{nav.find(n=>n[0]===page)?.[1]||'Мой профиль'}</b></div><div className="topbar-right"><span className="timezone"><Clock3 size={14}/>{tz}</span>{management&&<button className="icon-button" aria-label="Уведомления" onClick={()=>go('notifications')}><Bell size={19}/></button>}<button className="icon-button" aria-label="Выйти" onClick={()=>run(()=>api('/auth/logout','POST').then(()=>setUser(null)),'Вы вышли из системы')}><LogOut size={18}/></button></div></header><main className="content">{error&&<div className="error global-error" role="alert"><AlertCircle size={18}/>{error}<button onClick={()=>setError('')}>×</button></div>}{selected?<TicketDetail identifier={selected} onBack={()=>setSelected(null)} {...common}/>:<><div className="page-heading"><div><div className="eyebrow">АХО · СЕРВИС И ПОДДЕРЖКА</div><h1>{page==='overview'?'Обзор рабочего дня':nav.find(n=>n[0]===page)?.[1]||({profile:'Мой профиль',notifications:'Доставка уведомлений'} as Record<string,string>)[page]}</h1><p>{({overview:'Все обращения, сроки и нагрузка команды — на одном экране.',tickets:'От первого обращения до решенного вопроса.',receivers:'Подключение Telegram и правила доставки заявок команде.',analytics:'Показатели сервиса на основе реальных обращений.',users:'Сотрудники компании, регистрация и права доступа.'} as Record<string,string>)[page]||'Управляйте данными и настройками рабочего пространства.'}</p></div><div className="heading-actions"><button className="secondary icon-button" aria-label="Обновить" onClick={refresh}><RefreshCw size={17}/></button>{['overview','tickets'].includes(page)&&<button className="primary" onClick={()=>setCreate(true)}><Plus size={17}/>Новая заявка</button>}</div></div>
 {page==='overview'&&<Dashboard onOpen={setSelected} onAll={()=>go('tickets')} {...common}/>}
 {page==='tickets'&&<TicketList onOpen={setSelected} {...common}/>}
 {page==='analytics'&&<Analytics {...common}/>}
 {page==='reports'&&<TicketList onOpen={setSelected} reports {...common}/>}
 {page==='receivers'&&<Receivers {...common}/>}
 {page==='users'&&<UsersPage {...common}/>}
 {['departments','categories'].includes(page)&&<CatalogPage kind={page} {...common}/>}
 {page==='sla'&&<SlaPage {...common}/>}
 {page==='settings'&&<SettingsPage {...common}/>}
 {page==='audit'&&<LogPage kind="audit" {...common}/>}
 {page==='notifications'&&<LogPage kind="notifications" {...common}/>}
 {page==='profile'&&<ProfilePage {...common}/>}
 </>}</main><footer>АХО · Внутренний сервис компании <span>Единая история. Понятная ответственность.</span></footer></div>{create&&<CreateTicket onClose={()=>setCreate(false)} onCreated={id=>{setCreate(false);setSelected(id);refresh();notify('Заявка зарегистрирована');}} {...common}/>} {toast&&<div className="toast" role="status"><CheckCircle2 size={19}/>{toast}</div>}</div>;
}
type Common={user:User;run:(fn:()=>Promise<unknown>,message?:string)=>Promise<boolean>;refresh:()=>void;notify:(s:string)=>void;tz:string;cats:Catalog[];deps:Catalog[];receivers:Receiver[];version:number};
function useData<T>(path:string,version:number){const [data,setData]=useState<T|null>(null),[error,setError]=useState('');useEffect(()=>{let live=true;setError('');api<T>(path).then(x=>{if(live)setData(x);}).catch(e=>{if(live)setError(e.message);});return()=>{live=false;};},[path,version]);return {data,error};}
function Load({error}:{error?:string}){return error?<div className="error">{error}</div>:<div className="loading">Загрузка…</div>;}
function Kpis({s}:{s:Stats}){return <div className="kpi-grid">{[[s.new,'Новые заявки',Inbox,'blue'],[s.in_progress,'В работе',Activity,'green'],[s.overdue,'Просроченные',AlertCircle,'red'],[s.waiting,'Ожидают заявителя',Clock3,'amber']].map(([v,label,Icon,color])=>{const I=Icon as typeof Inbox;return <div className="kpi" key={String(label)}><div className="kpi-label">{String(label)}<span className={'kpi-icon '+color}><I size={18}/></span></div><strong>{String(v)}</strong><div className="kpi-foot">{label==='Просроченные'?'Требуют внимания команды':'В текущем периоде'}<ArrowUpRight size={14}/></div></div>;})}</div>;}
function Trend({rows}:{rows:Group[]}){return <div className="chart"><ResponsiveContainer width="100%" height={235}><AreaChart data={rows}><defs><linearGradient id="trend" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#288a75" stopOpacity={.22}/><stop offset="100%" stopColor="#288a75" stopOpacity={.01}/></linearGradient></defs><CartesianGrid vertical={false} stroke="#edf0f2"/><XAxis dataKey="name" tick={{fontSize:10,fill:'#8993a2'}} axisLine={false} tickLine={false} minTickGap={35}/><YAxis tick={{fontSize:11,fill:'#8993a2'}} axisLine={false} tickLine={false} width={28} allowDecimals={false}/><Tooltip contentStyle={{borderRadius:8,border:'1px solid #e7ebee'}}/><Area isAnimationActive={false} name="Заявки" type="monotone" dataKey="value" stroke="#288a75" strokeWidth={2.5} fill="url(#trend)"/></AreaChart></ResponsiveContainer></div>;}
function Breakdown({rows,labels}:{rows:Group[];labels?:Record<string,string>}){const max=Math.max(...rows.map(x=>x.value),1);return <div className="breakdown">{rows.length?rows.slice(0,7).map((r,i)=><div key={r.name}><div><span><i style={{background:['#278b75','#71a999','#9dc6b8','#bacfd7','#899caf','#516b88','#d0d8e1'][i]}}/>{labels?.[r.name]||r.name}</span><b>{r.value}</b></div><div className="bar-track"><span style={{width:`${r.value/max*100}%`}}/></div></div>):empty('Нет данных за период')}</div>;}
function Dashboard(p:Common&{onOpen:(id:string)=>void;onAll:()=>void}){const {data:s,error}=useData<Stats>('/analytics',p.version);const {data:t}=useData<{items:Ticket[]}>('/tickets?page_size=6',p.version);if(!s)return <Load error={error}/>;return <><Kpis s={s}/><div className="metrics-strip"><span><CheckCircle2 size={17}/>Выполнено сегодня <b>{s.completed_today}</b></span><span>Средняя реакция <b>{s.avg_response_hours} ч</b></span><span>Среднее выполнение <b>{s.avg_resolution_hours} ч</b></span><span><ShieldCheck size={17}/>SLA соблюден <b className="green-text">{s.sla_compliance}%</b></span></div><div className="dashboard-charts"><section className="panel"><div className="panel-head"><div><h2>Динамика обращений</h2><p>Количество заявок по дням</p></div><span className="subtle-tag">Вся история</span></div><Trend rows={s.daily}/></section><section className="panel"><div className="panel-head"><div><h2>Заявки по категориям</h2><p>Распределение обращений</p></div><Shapes size={18} className="muted"/></div><Breakdown rows={s.by_category}/></section></div><section className="panel"><div className="panel-head"><div><h2>Последние заявки <span className="count">{s.total}</span></h2><p>Новые обращения и текущий статус</p></div><button className="text-button" onClick={p.onAll}>Все заявки <ArrowUpRight size={16}/></button></div>{t&&<TicketTable rows={t.items} onOpen={p.onOpen} tz={p.tz}/>}</section><div className="bottom-grid"><section className="panel"><div className="panel-head"><h2>Нагрузка специалистов</h2><Users size={18} className="muted"/></div><div className="workload-list">{p.receivers.filter(r=>r.workload>0).slice(0,5).map((r,i)=><div key={r.id}><div className={'avatar pastel-'+i}>{r.first_name[0]}{r.last_name[0]}</div><div><b>{r.full_name}</b><small>{r.categories?.slice(0,2).join(', ')||'АХО'}</small></div><span>{r.workload} заявок</span></div>)}</div></section><section className="panel"><div className="panel-head"><h2>По департаментам</h2><Building2 size={18} className="muted"/></div><Breakdown rows={s.by_department}/></section></div></>;}
function TicketTable({rows,onOpen,tz}:{rows:Ticket[];onOpen:(id:string)=>void;tz:string}){if(!rows.length)return empty('Заявок не найдено');return <div className="table-wrap"><table><thead><tr><th>Заявка / дата</th><th>Обращение</th><th>Сотрудник</th><th>Приоритет</th><th>Статус</th><th>Ответственный / SLA</th><th/></tr></thead><tbody>{rows.map(t=><tr key={t.id} className="clickable" onClick={()=>onOpen(t.id)}><td><button className="ticket-link">{t.ticket_number}</button><small>{date(t.created_at,tz)}</small></td><td><b className="description-cell">{t.description}</b><small>{t.category} · {t.building}, {t.room}</small>{t.routing_required&&<span className="routing-tag">Нужно назначение</span>}</td><td><span>{t.requester.full_name}</span><small>{t.requester.department}</small></td><td><span className={'priority '+t.priority.toLowerCase()}><i/>{priorities[t.priority]}</span></td><td>{badge(t.status)}</td><td><span>{t.assignee?.full_name||'Не назначен'}</span><small className={t.sla==='BREACHED'?'red-text':'muted'}>{({WITHIN:'В пределах SLA',NEAR:'Приближается срок',BREACHED:'Срок SLA превышен',EXCLUDED:'Не учитывается'} as Record<string,string>)[t.sla]}</small></td><td><ChevronRight size={16} className="muted"/></td></tr>)}</tbody></table></div>;}
function TicketList(p:Common&{onOpen:(id:string)=>void;reports?:boolean}){
 const [filters,setFilters]=useState<Record<string,string>>({}),[page,setPage]=useState(1),[advanced,setAdvanced]=useState(false);
 const change=(k:string,v:string)=>{setFilters(f=>({...f,[k]:v}));setPage(1);};const query=new URLSearchParams(Object.fromEntries(Object.entries(filters).filter(([,v])=>v))).toString();
 const {data,error}=useData<{items:Ticket[];total:number}>(`/tickets?${query}&page=${page}&page_size=15`,p.version);
 return <section className="panel"><div className="filter-toolbar"><div className="search-box"><Search size={17}/><input aria-label="Поиск заявок" placeholder="Номер, описание, сотрудник или телефон…" value={filters.q||''} onChange={e=>change('q',e.target.value)}/></div><Select value={filters.status||''} onChange={v=>change('status',v)} options={Object.entries(statuses).map(([id,name])=>({id,name}))} placeholder="Все статусы"/><Select value={filters.category_id||''} onChange={v=>change('category_id',v)} options={p.cats} placeholder="Все категории"/><button className="secondary" onClick={()=>setAdvanced(!advanced)}><SlidersHorizontal size={16}/>Фильтры</button></div>{advanced&&<div className="advanced-filters"><Select value={filters.department_id||''} onChange={v=>change('department_id',v)} options={p.deps} placeholder="Все департаменты"/><Select value={filters.assigned_to||''} onChange={v=>change('assigned_to',v)} options={p.receivers.map(r=>({id:r.id,name:r.full_name}))} placeholder="Все специалисты"/><Select value={filters.priority||''} onChange={v=>change('priority',v)} options={Object.entries(priorities).map(([id,name])=>({id,name}))} placeholder="Все приоритеты"/><Select value={filters.sla||''} onChange={v=>change('sla',v)} options={[{id:'WITHIN',name:'В пределах SLA'},{id:'NEAR',name:'Приближается срок'},{id:'BREACHED',name:'SLA превышен'}]} placeholder="Любой SLA"/><Field label="Создана с"><input type="date" value={filters.date_from?.slice(0,10)||''} onChange={e=>change('date_from',e.target.value?e.target.value+'T00:00:00':'')}/></Field><Field label="По"><input type="date" value={filters.date_to?.slice(0,10)||''} onChange={e=>change('date_to',e.target.value?e.target.value+'T23:59:59':'')}/></Field><button className="text-button" onClick={()=>{setFilters({});setPage(1);}}>Сбросить</button></div>}{(p.reports||isManager(p.user))&&<div className="export-row"><span>{data?.total||0} заявок по выбранным условиям</span><a className="secondary" href={'/api/reports/export?format=csv&'+query}><FileDown size={15}/>CSV</a><a className="secondary" href={'/api/reports/export?format=xlsx&'+query}><FileDown size={15}/>XLSX</a></div>}{error?<Load error={error}/>:data?<TicketTable rows={data.items} onOpen={p.onOpen} tz={p.tz}/>:<Load/>}<div className="pagination"><span>Страница {page} из {Math.max(1,Math.ceil((data?.total||0)/15))}</span><div><button className="secondary" disabled={page===1} onClick={()=>setPage(page-1)}><ChevronLeft size={16}/></button><button className="secondary" disabled={page*15>=(data?.total||0)} onClick={()=>setPage(page+1)}><ChevronRight size={16}/></button></div></div></section>;
}
function CreateTicket(p:Common&{onClose:()=>void;onCreated:(id:string)=>void}){
 const [data,setData]=useState({category_id:p.cats.find(c=>c.active)?.id||'',description:'',building:p.user.building||'',floor:p.user.floor||'',room:p.user.room||'',requested_urgency:'NORMAL'}),[preview,setPreview]=useState(false),[busy,setBusy]=useState(false),[error,setError]=useState('');
 const set=(k:string,v:string)=>setData(d=>({...d,[k]:v}));
 async function submit(e:FormEvent){e.preventDefault();if(!preview){setPreview(true);return;}setBusy(true);try{const t=await api<Ticket>('/tickets','POST',data);p.onCreated(t.id);}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
 return <Dialog title={preview?'Подтвердите заявку':'Новая заявка'} onClose={p.onClose}><form onSubmit={submit} className="form-grid">{preview?<div className="request-preview"><h3>{p.cats.find(c=>c.id===data.category_id)?.name}</h3><p>{data.description}</p><dl><dt>Место</dt><dd>{data.building}, этаж {data.floor}, кабинет {data.room}</dd><dt>Срочность</dt><dd>{data.requested_urgency==='URGENT'?'Срочная':'Обычная'}</dd><dt>Заявитель</dt><dd>{p.user.full_name}</dd></dl><p className="hint">После отправки заявка будет сохранена и направлена получателям АХО.</p></div>:<><Field label="Категория"><Select value={data.category_id} onChange={v=>set('category_id',v)} options={p.cats.filter(c=>c.active)}/></Field><Field label="Описание проблемы"><textarea required minLength={5} maxLength={2000} rows={4} placeholder="Опишите, что произошло и какая помощь нужна" value={data.description} onChange={e=>set('description',e.target.value)}/></Field><div className="form-row"><Field label="Здание"><input required value={data.building} onChange={e=>set('building',e.target.value)}/></Field><Field label="Этаж"><input required value={data.floor} onChange={e=>set('floor',e.target.value)}/></Field><Field label="Кабинет"><input required value={data.room} onChange={e=>set('room',e.target.value)}/></Field></div><Field label="Запрашиваемая срочность"><Select value={data.requested_urgency} onChange={v=>set('requested_urgency',v)} options={[{id:'NORMAL',name:'Обычная'},{id:'URGENT',name:'Срочная'}]}/></Field><p className="hint"><Paperclip size={15}/> Фото и документы можно приложить через Telegram-бот.</p></>}{error&&<div className="error">{error}</div>}<div className="form-actions"><button type="button" className="secondary" onClick={()=>preview?setPreview(false):p.onClose()}>{preview?'Изменить':'Отмена'}</button><button className="primary" disabled={busy}>{busy?'Отправляем…':preview?'Отправить заявку':'Проверить заявку'}<ArrowUpRight size={16}/></button></div></form></Dialog>;
}
function TicketDetail(p:Common&{identifier:string;onBack:()=>void}){
 const {data:t,error}=useData<Ticket>('/tickets/'+p.identifier,p.version),[text,setText]=useState(''),[internal,setInternal]=useState(false),[action,setAction]=useState(''),[reason,setReason]=useState(''),[assigned,setAssigned]=useState(''),[priority,setPriority]=useState('NORMAL'),[busy,setBusy]=useState(false);
 const staff=isStaff(p.user),own=t?.requester.id===p.user.id,operational=staff&&(isManager(p.user)||t?.assigned_to===p.user.id);
 if(!t)return <Load error={error}/>;
 const doAction=async(a:string,body:unknown={})=>{setBusy(true);const ok=await p.run(()=>api(`/tickets/${t.id}/actions/${a}`,'POST',body));setBusy(false);if(ok){setAction('');setReason('');}};
 const actions:{id:string;label:string;reason?:boolean}[]=[];
 if(staff&&t.status==='NEW')actions.push({id:'accept',label:'Принять заявку'});
 if(operational&&['ACCEPTED','REOPENED','WAITING_REQUESTER','WAITING_MATERIAL','ON_HOLD'].includes(t.status))actions.push({id:'start',label:'Начать / продолжить работу'});
 if(operational&&t.status==='IN_PROGRESS')actions.push({id:'request-info',label:'Запросить информацию',reason:true},{id:'wait-material',label:'Ожидаются материалы',reason:true},{id:'hold',label:'Приостановить',reason:true},{id:'complete',label:'Завершить работу',reason:true});
 if(own&&t.status==='COMPLETED')actions.push({id:'confirm',label:'Все выполнено'},{id:'reopen',label:'Проблема осталась',reason:true});
 if(own&&!['CLOSED','CANCELLED','COMPLETED'].includes(t.status))actions.push({id:'cancel',label:t.status==='NEW'?'Отменить заявку':'Запросить отмену',reason:true});
 if(operational&&t.cancellation_requested)actions.push({id:'approve-cancel',label:'Одобрить отмену'});
 if(staff)actions.push({id:'escalate',label:'Эскалировать',reason:true});
 return <><button className="text-button back" onClick={p.onBack}><ArrowLeft size={16}/>К списку заявок</button><div className="detail-heading"><div><span className="eyebrow">КАРТОЧКА ОБРАЩЕНИЯ</span><h1>{t.ticket_number}</h1><p>Создана {date(t.created_at,p.tz)} · Обновлена {date(t.updated_at,p.tz)}</p></div><div>{badge(t.status)}<span className={'priority '+t.priority.toLowerCase()}>{priorities[t.priority]}</span></div></div>{t.cancellation_requested&&<div className="notice">Заявитель просит отменить заявку: {t.cancellation_requested}</div>}<div className="detail-grid"><div><section className="panel padded"><h2>{t.category}</h2><p className="ticket-description">{t.description}</p><div className="location-line"><Building2 size={18}/>{t.building} · Этаж {t.floor} · Кабинет {t.room}</div>{t.attachments?.length?<div className="attachments">{t.attachments.map(a=><a key={a.id} className="secondary" href={'/api/attachments/'+a.id+'/download'}><Paperclip size={15}/>{a.file_name}</a>)}</div>:null}</section><section className="panel"><div className="panel-head"><h2><MessageSquare size={18}/>Переписка</h2><span className="count">{t.messages?.length||0}</span></div><div className="messages">{t.messages?.length?t.messages.map(m=><div key={m.id} className={'message '+(m.visibility==='INTERNAL'?'internal':'')}><div><b>{m.author}</b><small>{date(m.created_at,p.tz)} {m.visibility==='INTERNAL'&&'· Внутренняя заметка'}</small></div><p>{m.text}</p></div>):<p className="muted">Пока нет сообщений. Уточните детали или добавьте комментарий.</p>}</div><form className="message-form" onSubmit={async e=>{e.preventDefault();if(await p.run(()=>api(`/tickets/${t.id}/comments`,'POST',{text,visibility:internal?'INTERNAL':'PUBLIC'}),'Комментарий добавлен'))setText('');}}><textarea aria-label="Комментарий" required value={text} maxLength={4000} rows={3} onChange={e=>setText(e.target.value)} placeholder={internal?'Внутренняя заметка для АХО':'Написать комментарий…'}/><div>{staff?<label className="checkbox"><input type="checkbox" checked={internal} onChange={e=>setInternal(e.target.checked)}/>Внутренняя заметка</label>:<span/>}<button className="primary"><Send size={15}/>Отправить</button></div></form></section><section className="panel padded"><h2>История заявки</h2><div className="timeline">{t.history?.map(h=><div key={h.id}><i/><div><b>{statuses[h.new_status]}</b><small>{date(h.created_at,p.tz)}</small>{h.comment&&<p>{h.comment}</p>}</div></div>)}</div>{staff&&<details><summary>Журнал действий</summary>{t.audit?.map((a,i)=><p key={i} className="hint">{date(a.timestamp,p.tz)} · {a.action} · {a.source}</p>)}</details>}</section></div><aside><section className="panel padded"><h2>Действия</h2><div className="action-stack">{actions.map(a=><button disabled={busy} key={a.id} className={['accept','start','complete','confirm'].includes(a.id)?'primary':'secondary'} onClick={()=>a.reason?(setAction(a.id),setReason('')):doAction(a.id)}>{a.label}</button>)}{!actions.length&&<p className="muted">Нет доступных действий</p>}</div>{own&&t.status==='CLOSED'&&<div className="rating"><p>{t.rating?'Ваша оценка':'Оцените качество выполнения'}</p>{t.rating?<strong>{'★'.repeat(t.rating)}</strong>:[1,2,3,4,5].map(n=><button key={n} aria-label={`Оценить ${n}`} onClick={()=>doAction('rate',{score:n})}>{n} ★</button>)}</div>}</section><section className="panel padded"><h2>Заявитель</h2><div className="person"><div className="avatar">{t.requester.first_name[0]}{t.requester.last_name[0]}</div><div><b>{t.requester.full_name}</b><small>{t.requester.department}</small></div></div><dl><dt>Мобильный</dt><dd><a href={'tel:'+t.requester.mobile_phone}>{t.requester.mobile_phone||'—'}</a></dd><dt>Внутренний</dt><dd>{t.requester.internal_phone||'—'}</dd></dl></section><section className="panel padded"><h2>Ответственный</h2><p>{t.assignee?.full_name||'Еще не назначен'}</p>{isManager(p.user)&&!['CLOSED','CANCELLED','COMPLETED'].includes(t.status)&&<><Select value={assigned} onChange={setAssigned} placeholder="Выбрать специалиста" options={p.receivers.filter(r=>r.receiver_status==='ACTIVE').map(r=>({id:r.id,name:r.full_name+` (${r.workload})`}))}/><button className="secondary full" disabled={!assigned} onClick={()=>doAction('assign',{assignee_id:assigned})}>Назначить</button><Field label="Приоритет"><Select value={priority} onChange={setPriority} options={Object.entries(priorities).map(([id,name])=>({id,name}))}/></Field><button className="secondary full" onClick={()=>doAction('priority',{priority})}>Изменить приоритет</button></>}</section><section className="panel padded"><h2>Контроль SLA</h2>{badge(t.sla,({BREACHED:'Срок превышен',WITHIN:'В пределах срока',NEAR:'Срок приближается',EXCLUDED:'Не учитывается'} as Record<string,string>)[t.sla])}<dl><dt>Принять до</dt><dd>{date(t.response_deadline,p.tz)}</dd><dt>Выполнить до</dt><dd>{date(t.resolution_deadline,p.tz)}</dd></dl></section></aside></div>{action&&<Dialog title={actions.find(a=>a.id===action)?.label||'Комментарий'} onClose={()=>setAction('')}><form className="form-grid" onSubmit={e=>{e.preventDefault();doAction(action,{comment:reason});}}><Field label="Комментарий / причина"><textarea required minLength={1} maxLength={4000} rows={4} value={reason} onChange={e=>setReason(e.target.value)}/></Field><button className="primary" disabled={busy}>Подтвердить</button></form></Dialog>}</>;
}
function Analytics(p:Common){const [from,setFrom]=useState(''),[to,setTo]=useState(''),[period,setPeriod]=useState('daily');const query=new URLSearchParams();if(from)query.set('date_from',from+'T00:00:00');if(to)query.set('date_to',to+'T23:59:59');const {data:s,error}=useData<Stats>('/analytics?'+query,p.version);if(!s)return <Load error={error}/>;return <><div className="date-controls"><Field label="С"><input type="date" value={from} onChange={e=>setFrom(e.target.value)}/></Field><Field label="По"><input type="date" value={to} onChange={e=>setTo(e.target.value)}/></Field><Select value={period} onChange={setPeriod} options={[{id:'daily',name:'По дням'},{id:'weekly',name:'По неделям'},{id:'monthly',name:'По месяцам'}]}/></div><Kpis s={s}/><div className="metrics-strip"><span>Всего <b>{s.total}</b></span><span>SLA <b>{s.sla_compliance}%</b></span><span>Повторные обращения <b>{s.reopen_rate}%</b></span><span>Средняя оценка <b>{s.satisfaction||'—'} / 5</b></span></div><section className="panel"><div className="panel-head"><h2>Динамика обращений</h2></div><Trend rows={s[period as 'daily'|'weekly'|'monthly']}/></section><div className="bottom-grid">{([['Категории',s.by_category],['Департаменты',s.by_department],['Статусы',s.by_status],['Приоритеты',s.by_priority],['Расположение',s.by_location],['Специалисты',s.by_specialist],['Повторяющиеся проблемы',s.recurring]] as [string,Group[]][]).map(([name,rows])=><section className="panel" key={name}><div className="panel-head"><h2>{name}</h2></div><Breakdown rows={rows} labels={{...statuses,...priorities}}/></section>)}</div></>;}
function CatalogPage(p:Common&{kind:string}){const rows=p.kind==='categories'?p.cats:p.deps;const [edit,setEdit]=useState<Catalog|null>(null),[name,setName]=useState(''),[show,setShow]=useState(false);const admin=p.user.roles.includes('ADMIN');return <section className="panel"><div className="panel-head"><h2>Справочник <span className="count">{rows.length}</span></h2>{admin&&<button className="primary" onClick={()=>{setEdit(null);setName('');setShow(true);}}><Plus size={16}/>Добавить</button>}</div><div className="table-wrap"><table><thead><tr><th>Название</th><th>Состояние</th><th>Действия</th></tr></thead><tbody>{rows.map(r=><tr key={r.id}><td><b>{r.name}</b></td><td>{badge(r.active?'ACTIVE':'DISABLED',r.active?'Активен':'В архиве')}</td><td>{admin&&<div className="row-actions"><button className="text-button" onClick={()=>{setEdit(r);setName(r.name);setShow(true);}}>Изменить</button><button className="text-button" onClick={()=>p.run(()=>api(`/catalog/${p.kind}/${r.id}`,'PATCH',{name:r.name,active:!r.active}))}>{r.active?'Архивировать':'Восстановить'}</button></div>}</td></tr>)}</tbody></table></div>{show&&<Dialog title={edit?'Изменить запись':'Добавить запись'} onClose={()=>setShow(false)}><form className="form-grid" onSubmit={async e=>{e.preventDefault();if(await p.run(()=>api('/catalog/'+p.kind+(edit?'/'+edit.id:''),edit?'PATCH':'POST',{name,active:edit?.active??true})))setShow(false);}}><Field label="Название"><input required minLength={2} maxLength={120} value={name} onChange={e=>setName(e.target.value)}/></Field><button className="primary">Сохранить</button></form></Dialog>}</section>;}
